CREATE OR REPLACE FUNCTION app_private.cerrar_mesa_qr_segura(p_mesa_id uuid, p_pedidos_ids uuid[], p_descuento numeric DEFAULT 0, p_propina numeric DEFAULT 0, p_metodo_pago text DEFAULT 'tarjeta'::text, p_notas text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_mesa public.sala_mesas%rowtype;
  v_num_pedidos integer;
  v_total_bruto numeric;
  v_descuento numeric;
  v_propina numeric;
  v_total_cobrado numeric;
  v_metodo text;
  v_cierre_id uuid;
  v_new_token text;
  v_new_expires_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select *
  into v_mesa
  from public.sala_mesas
  where id = p_mesa_id
  for update;

  if not found or not public.user_can_access_restaurant(v_mesa.restaurante_id) then
    raise exception 'MESA_NO_AUTORIZADA';
  end if;

  if p_pedidos_ids is null or cardinality(p_pedidos_ids) = 0 then
    raise exception 'PEDIDOS_REQUERIDOS';
  end if;

  select count(*)::integer, coalesce(sum(p.total), 0)
  into v_num_pedidos, v_total_bruto
  from public.pedidos_qr as p
  where p.id = any(p_pedidos_ids)
    and p.restaurante_id = v_mesa.restaurante_id
    and p.mesa_id = v_mesa.id
    and p.mesa_session_id = v_mesa.qr_session_id
    and not (
      lower(coalesce(p.estado, '')) = any (
        array['cobrado','cobrada','cerrado','cerrada','cancelado','cancelada']
      )
    );

  if v_num_pedidos <> cardinality(p_pedidos_ids) then
    raise exception 'PEDIDOS_NO_VALIDOS';
  end if;

  v_descuento := least(greatest(coalesce(p_descuento, 0), 0), v_total_bruto);
  v_propina := least(greatest(coalesce(p_propina, 0), 0), 10000);
  v_total_cobrado := greatest(0, v_total_bruto - v_descuento + v_propina);
  v_metodo := lower(trim(coalesce(p_metodo_pago, 'tarjeta')));

  if v_metodo <> all(array['tarjeta','efectivo','bizum','mixto']) then
    v_metodo := 'tarjeta';
  end if;

  insert into public.cierres_mesa_qr (
    restaurante_id, mesa_id, mesa_session_id, mesa, pedidos_ids,
    total_bruto, descuento, propina, total_cobrado, metodo_pago, notas
  )
  values (
    v_mesa.restaurante_id, v_mesa.id, v_mesa.qr_session_id, v_mesa.nombre,
    p_pedidos_ids, v_total_bruto, v_descuento, v_propina,
    v_total_cobrado, v_metodo, left(nullif(trim(coalesce(p_notas, '')), ''), 500)
  )
  returning id into v_cierre_id;

  update public.pedidos_qr
  set estado = 'cobrado',
      updated_at = now()
  where id = any(p_pedidos_ids);

  v_new_token := encode(extensions.gen_random_bytes(24), 'hex');
  v_new_expires_at := now() + interval '12 hours';

  update public.sala_mesas
  set qr_access_token = v_new_token,
      qr_session_id = gen_random_uuid(),
      qr_expires_at = v_new_expires_at,
      updated_at = now()
  where id = v_mesa.id;

  return jsonb_build_object(
    'ok', true,
    'cierre_id', v_cierre_id,
    'total_cobrado', v_total_cobrado,
    'nueva_url_generada', true,
    'expires_at', v_new_expires_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION app_private.enforce_client_contact_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_whatsapp boolean := false;
  v_email boolean := false;
begin
  select
    coalesce(bool_or(c.review_whatsapp or c.loyalty_whatsapp), false),
    coalesce(bool_or(c.review_email or c.loyalty_email), false)
  into v_whatsapp, v_email
  from public.cliente_comunicaciones_consentimiento as c
  where c.restaurante_id = new.restaurante_id
    and c.cliente_id = new.id
    and c.revoked_at is null;

  new.permite_whatsapp := v_whatsapp;
  new.permite_email := v_email;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.guardar_configuracion_web_reservas(p_restaurante_id uuid, p_web jsonb, p_config jsonb, p_horarios jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_nombre text := nullif(left(trim(coalesce(p_web ->> 'nombre_publico', '')), 120), '');
  v_zona_horaria text := coalesce(nullif(trim(p_config ->> 'zona_horaria'), ''), 'Europe/Madrid');
  v_publicada boolean := coalesce((p_web ->> 'publicada')::boolean, false);
  v_reservas_activas boolean := coalesce((p_config ->> 'activo')::boolean, false);
  v_slug text;
begin
  if p_restaurante_id is null
     or not public.user_can_access_restaurant(p_restaurante_id) then
    raise exception 'ACCESS_DENIED';
  end if;

  if v_nombre is null then
    raise exception 'PUBLIC_NAME_REQUIRED';
  end if;

  if jsonb_typeof(coalesce(p_horarios, '[]'::jsonb)) <> 'array' then
    raise exception 'INVALID_SCHEDULE';
  end if;

  if not exists (
    select 1 from pg_timezone_names tz where tz.name = v_zona_horaria
  ) then
    raise exception 'INVALID_TIMEZONE';
  end if;

  update public.restaurante_webs
  set publicada = v_publicada,
      nombre_publico = v_nombre,
      antetitulo = nullif(left(trim(coalesce(p_web ->> 'antetitulo', '')), 120), ''),
      titular = nullif(left(trim(coalesce(p_web ->> 'titular', '')), 180), ''),
      subtitulo = nullif(left(trim(coalesce(p_web ->> 'subtitulo', '')), 360), ''),
      descripcion = nullif(left(trim(coalesce(p_web ->> 'descripcion', '')), 2000), ''),
      direccion_publica = nullif(left(trim(coalesce(p_web ->> 'direccion_publica', '')), 260), ''),
      telefono_publico = nullif(left(trim(coalesce(p_web ->> 'telefono_publico', '')), 40), ''),
      email_publico = nullif(lower(left(trim(coalesce(p_web ->> 'email_publico', '')), 254)), ''),
      whatsapp = nullif(left(trim(coalesce(p_web ->> 'whatsapp', '')), 40), ''),
      google_maps_url = nullif(left(trim(coalesce(p_web ->> 'google_maps_url', '')), 1000), ''),
      instagram_url = nullif(left(trim(coalesce(p_web ->> 'instagram_url', '')), 1000), ''),
      facebook_url = nullif(left(trim(coalesce(p_web ->> 'facebook_url', '')), 1000), ''),
      logo_url = nullif(left(trim(coalesce(p_web ->> 'logo_url', '')), 1000), ''),
      hero_image_url = nullif(left(trim(coalesce(p_web ->> 'hero_image_url', '')), 1000), ''),
      galeria_urls = array(
        select left(trim(value), 1000)
        from jsonb_array_elements_text(coalesce(p_web -> 'galeria_urls', '[]'::jsonb))
        where trim(value) <> ''
        limit 12
      ),
      especialidades = array(
        select left(trim(value), 80)
        from jsonb_array_elements_text(coalesce(p_web -> 'especialidades', '[]'::jsonb))
        where trim(value) <> ''
        limit 12
      ),
      color_primario = coalesce(nullif(trim(p_web ->> 'color_primario'), ''), '#123c3a'),
      color_acento = coalesce(nullif(trim(p_web ->> 'color_acento'), ''), '#e7b75f'),
      color_fondo = coalesce(nullif(trim(p_web ->> 'color_fondo'), ''), '#f7f3e8'),
      seo_titulo = nullif(left(trim(coalesce(p_web ->> 'seo_titulo', '')), 180), ''),
      seo_descripcion = nullif(left(trim(coalesce(p_web ->> 'seo_descripcion', '')), 320), '')
  where restaurante_id = p_restaurante_id
  returning slug into v_slug;

  if v_slug is null then
    raise exception 'WEB_CONFIG_MISSING';
  end if;

  update public.reservas_config
  set activo = v_reservas_activas,
      zona_horaria = v_zona_horaria,
      intervalo_minutos = greatest(5, least(120, coalesce((p_config ->> 'intervalo_minutos')::integer, 30))),
      duracion_minutos = greatest(15, least(720, coalesce((p_config ->> 'duracion_minutos')::integer, 90))),
      capacidad_por_turno = greatest(1, least(5000, coalesce((p_config ->> 'capacidad_por_turno')::integer, 40))),
      personas_minimas = greatest(1, least(100, coalesce((p_config ->> 'personas_minimas')::integer, 1))),
      personas_maximas = greatest(1, least(500, coalesce((p_config ->> 'personas_maximas')::integer, 12))),
      antelacion_minutos = greatest(0, least(43200, coalesce((p_config ->> 'antelacion_minutos')::integer, 60))),
      dias_maximos_antelacion = greatest(1, least(730, coalesce((p_config ->> 'dias_maximos_antelacion')::integer, 60))),
      confirmacion_automatica = coalesce((p_config ->> 'confirmacion_automatica')::boolean, true),
      cancelacion_minutos = greatest(0, least(10080, coalesce((p_config ->> 'cancelacion_minutos')::integer, 120))),
      requiere_telefono = coalesce((p_config ->> 'requiere_telefono')::boolean, true),
      requiere_email = coalesce((p_config ->> 'requiere_email')::boolean, false),
      aviso_reserva = nullif(left(trim(coalesce(p_config ->> 'aviso_reserva', '')), 500), ''),
      politica_cancelacion = nullif(left(trim(coalesce(p_config ->> 'politica_cancelacion', '')), 800), '')
  where restaurante_id = p_restaurante_id;

  if (
    select personas_maximas < personas_minimas
    from public.reservas_config
    where restaurante_id = p_restaurante_id
  ) then
    raise exception 'INVALID_PARTY_RANGE';
  end if;

  delete from public.reservas_horarios
  where restaurante_id = p_restaurante_id;

  insert into public.reservas_horarios (
    restaurante_id,
    dia_semana,
    turno,
    hora_inicio,
    hora_fin,
    capacidad_override,
    activo
  )
  select
    p_restaurante_id,
    x.dia_semana,
    lower(trim(x.turno)),
    x.hora_inicio,
    x.hora_fin,
    x.capacidad_override,
    coalesce(x.activo, true)
  from jsonb_to_recordset(coalesce(p_horarios, '[]'::jsonb)) as x(
    dia_semana smallint,
    turno text,
    hora_inicio time,
    hora_fin time,
    capacidad_override integer,
    activo boolean
  )
  where coalesce(x.activo, true) = true;

  if v_reservas_activas and not exists (
    select 1
    from public.reservas_horarios h
    where h.restaurante_id = p_restaurante_id and h.activo = true
  ) then
    raise exception 'ACTIVE_BOOKING_REQUIRES_SCHEDULE';
  end if;

  return jsonb_build_object(
    'ok', true,
    'slug', v_slug,
    'publicada', v_publicada,
    'reservas_activas', v_reservas_activas
  );
end;
$function$

CREATE OR REPLACE FUNCTION app_private.registrar_consumo_reserva(p_reserva_id uuid, p_restaurante_id uuid, p_gasto numeric, p_metodo_pago text DEFAULT 'no_indicado'::text, p_notas text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.user_can_access_restaurant(p_restaurante_id) then
    raise exception 'ACCESS_DENIED';
  end if;

  return public.registrar_consumo_reserva_interno(
    p_reserva_id,
    p_restaurante_id,
    p_gasto,
    p_metodo_pago,
    p_notas
  );
end;
$function$

CREATE OR REPLACE FUNCTION app_private.renovar_acceso_mesa_qr(p_mesa_id uuid, p_duracion_horas integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_mesa public.sala_mesas%rowtype;
  v_horas integer := greatest(1, least(24, coalesce(p_duracion_horas, 12)));
  v_token text;
  v_expires_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select *
  into v_mesa
  from public.sala_mesas
  where id = p_mesa_id
  for update;

  if not found or not public.user_can_access_restaurant(v_mesa.restaurante_id) then
    raise exception 'MESA_NO_AUTORIZADA';
  end if;

  if exists (
    select 1
    from public.pedidos_qr as p
    where p.mesa_id = v_mesa.id
      and p.mesa_session_id = v_mesa.qr_session_id
      and not (
        lower(coalesce(p.estado, '')) = any (
          array['cobrado','cobrada','cerrado','cerrada','cancelado','cancelada']
        )
      )
  ) then
    raise exception 'MESA_CON_PEDIDOS_ABIERTOS';
  end if;

  v_token := encode(extensions.gen_random_bytes(24), 'hex');
  v_expires_at := now() + (v_horas * interval '1 hour');

  update public.sala_mesas
  set qr_access_token = v_token,
      qr_session_id = gen_random_uuid(),
      qr_expires_at = v_expires_at,
      updated_at = now()
  where id = v_mesa.id;

  return jsonb_build_object(
    'ok', true,
    'mesa_id', v_mesa.id,
    'access_token', v_token,
    'expires_at', v_expires_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION app_private.sync_client_contact_permissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_restaurante_id uuid;
  v_cliente_id uuid;
begin
  if tg_op = 'DELETE' then
    v_restaurante_id := old.restaurante_id;
    v_cliente_id := old.cliente_id;
  else
    v_restaurante_id := new.restaurante_id;
    v_cliente_id := new.cliente_id;
  end if;

  update public.clientes as cliente
  set permite_whatsapp = exists (
        select 1
        from public.cliente_comunicaciones_consentimiento as c
        where c.restaurante_id = v_restaurante_id
          and c.cliente_id = v_cliente_id
          and c.revoked_at is null
          and (c.review_whatsapp or c.loyalty_whatsapp)
      ),
      permite_email = exists (
        select 1
        from public.cliente_comunicaciones_consentimiento as c
        where c.restaurante_id = v_restaurante_id
          and c.cliente_id = v_cliente_id
          and c.revoked_at is null
          and (c.review_email or c.loyalty_email)
      ),
      updated_at = now()
  where cliente.restaurante_id = v_restaurante_id
    and cliente.id = v_cliente_id;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.validar_asignacion_mesa_reserva()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_mesa public.sala_mesas%rowtype;
  v_zona_horaria text;
  v_duracion integer;
  v_inicio timestamptz;
  v_fin timestamptz;
begin
  select coalesce(c.zona_horaria, 'Europe/Madrid'),
         coalesce(c.duracion_minutos, 90)
    into v_zona_horaria, v_duracion
  from public.reservas_config c
  where c.restaurante_id = new.restaurante_id;

  v_zona_horaria := coalesce(v_zona_horaria, 'Europe/Madrid');
  v_duracion := coalesce(v_duracion, 90);

  if current_setting('app.allow_demo_write', true) = '1'
     and exists (
       select 1
       from public.usuarios_restaurantes ur
       where ur.restaurante_id = new.restaurante_id
         and ur.demo_vista is true
     ) then
    if new.fecha_hora_reserva is not null then
      new.inicio_at := new.fecha_hora_reserva at time zone v_zona_horaria;
      new.fin_at := new.inicio_at + make_interval(mins => v_duracion);
    end if;
    return new;
  end if;

  if new.mesa_id is null
     or lower(coalesce(new.estado, 'pendiente'))
       in ('cancelada', 'cancelado', 'no-show', 'no_show', 'no show') then
    return new;
  end if;

  v_inicio := coalesce(
    new.inicio_at,
    new.fecha_hora_reserva at time zone v_zona_horaria
  );
  v_fin := coalesce(new.fin_at, v_inicio + make_interval(mins => v_duracion));

  if v_inicio is null or v_fin is null or v_fin <= v_inicio then
    raise exception 'INVALID_RESERVATION_TIME';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('table:' || new.mesa_id::text, 0));

  select m.*
    into v_mesa
  from public.sala_mesas m
  where m.id = new.mesa_id
  for update;

  if v_mesa.id is null or v_mesa.restaurante_id <> new.restaurante_id then
    raise exception 'TABLE_NOT_FOUND';
  end if;

  if not v_mesa.activa or v_mesa.bloqueada then
    raise exception 'TABLE_NOT_AVAILABLE';
  end if;

  if v_mesa.capacidad < greatest(coalesce(new.personas, 1), 1) then
    raise exception 'TABLE_CAPACITY_EXCEEDED';
  end if;

  if exists (
    select 1
    from public.reservas r
    left join public.reservas_config c on c.restaurante_id = r.restaurante_id
    where r.mesa_id = new.mesa_id
      and r.id is distinct from new.id
      and lower(coalesce(r.estado, 'pendiente'))
        not in ('cancelada', 'cancelado', 'no-show', 'no_show', 'no show')
      and coalesce(
        r.inicio_at,
        r.fecha_hora_reserva at time zone coalesce(c.zona_horaria, 'Europe/Madrid')
      ) < v_fin
      and coalesce(
        r.fin_at,
        (r.fecha_hora_reserva at time zone coalesce(c.zona_horaria, 'Europe/Madrid'))
          + make_interval(mins => coalesce(c.duracion_minutos, 90))
      ) > v_inicio
  ) then
    raise exception 'TABLE_TIME_CONFLICT';
  end if;

  new.inicio_at := v_inicio;
  new.fin_at := v_fin;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_cancelar_instalacion_pendiente(p_admin_user_id uuid, p_restaurante_id uuid, p_invitation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from public.app_admins a where a.user_id = p_admin_user_id
  ) then
    raise exception 'ADMIN_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.restaurant_invitations i
    where i.id = p_invitation_id
      and i.restaurante_id = p_restaurante_id
      and i.status = 'pending'
      and i.auth_user_id is null
  ) then
    return false;
  end if;

  delete from public.sala_mesas where restaurante_id = p_restaurante_id;
  delete from public.sala_zonas where restaurante_id = p_restaurante_id;
  delete from public.menus_dia_qr where restaurante_id = p_restaurante_id;
  delete from public.carta_categorias where restaurante_id = p_restaurante_id;
  delete from public.carta_productos where restaurante_id = p_restaurante_id;
  delete from public.cartas_digitales where restaurante_id = p_restaurante_id;
  delete from public.restaurante_modulos where restaurante_id = p_restaurante_id;
  delete from public.restaurant_invitations where id = p_invitation_id;
  delete from public.restaurantes where id = p_restaurante_id;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_crear_instalacion_restaurante(p_admin_user_id uuid, p_nombre text, p_telefono text DEFAULT NULL::text, p_direccion text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_capacidad integer DEFAULT 40, p_mesas integer DEFAULT 8, p_plan text DEFAULT 'premium'::text, p_carta_nombre text DEFAULT 'Carta principal'::text, p_reservas boolean DEFAULT true, p_clientes boolean DEFAULT true, p_resenas boolean DEFAULT true, p_fidelizacion boolean DEFAULT true, p_metricas boolean DEFAULT true, p_chatbot boolean DEFAULT false, p_camarero_digital boolean DEFAULT true, p_menu_digital boolean DEFAULT true, p_automatizaciones boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_restaurante_id uuid := gen_random_uuid();
  v_invitation_id uuid := gen_random_uuid();
  v_carta_id uuid;
  v_zona_id uuid;
  v_token text;
  v_slug text;
  v_email text := lower(trim(coalesce(p_email, '')));
  v_total_mesas integer := greatest(1, least(80, coalesce(p_mesas, 8)));
begin
  if not exists (
    select 1 from public.app_admins a where a.user_id = p_admin_user_id
  ) then
    raise exception 'ADMIN_REQUIRED';
  end if;

  if nullif(trim(coalesce(p_nombre, '')), '') is null then
    raise exception 'NAME_REQUIRED';
  end if;

  if v_email = '' or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    raise exception 'VALID_EMAIL_REQUIRED';
  end if;

  if exists (select 1 from auth.users u where lower(u.email) = v_email) then
    raise exception 'EMAIL_ALREADY_REGISTERED';
  end if;

  if exists (
    select 1
    from public.restaurant_invitations i
    where lower(i.email) = v_email and i.status in ('pending', 'sent')
  ) then
    raise exception 'INVITATION_ALREADY_EXISTS';
  end if;

  v_slug := lower(regexp_replace(trim(p_nombre), '[^a-zA-Z0-9]+', '-', 'g'));
  v_slug := regexp_replace(v_slug, '(^-|-$)', '', 'g');
  if v_slug = '' then v_slug := 'restaurante'; end if;
  v_slug := v_slug || '-' || substring(replace(v_restaurante_id::text, '-', '') from 1 for 6);

  insert into public.restaurantes (
    id, nombre, slug, telefono, direccion, email_notificaciones,
    capacidad_total, owner_id, color_primario, color_fondo
  ) values (
    v_restaurante_id,
    trim(p_nombre),
    v_slug,
    nullif(trim(coalesce(p_telefono, '')), ''),
    nullif(trim(coalesce(p_direccion, '')), ''),
    v_email,
    greatest(1, least(5000, coalesce(p_capacidad, 40))),
    null,
    '#2563eb',
    '#f8fafc'
  );

  insert into public.restaurant_invitations (
    id, restaurante_id, email, invited_by, status
  ) values (
    v_invitation_id, v_restaurante_id, v_email, p_admin_user_id, 'pending'
  );

  insert into public.restaurante_modulos (
