CREATE OR REPLACE FUNCTION public.block_demo_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if current_setting('app.allow_demo_write', true) = '1' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if public.is_demo_user() then
    raise exception 'DEMO_READ_ONLY'
      using errcode = '42501',
            hint = 'La cuenta de demostración es de solo lectura.';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancelar_reserva_publica_gestion(p_gestion_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reserva_id uuid;
  v_estado text;
  v_inicio_at timestamptz;
  v_cancelacion_minutos integer;
  v_zona_horaria text;
begin
  select
    r.id,
    r.estado,
    coalesce(r.inicio_at, r.fecha_hora_reserva at time zone c.zona_horaria),
    c.cancelacion_minutos,
    c.zona_horaria
  into
    v_reserva_id,
    v_estado,
    v_inicio_at,
    v_cancelacion_minutos,
    v_zona_horaria
  from public.reservas r
  join public.reservas_config c on c.restaurante_id = r.restaurante_id
  where r.gestion_token = p_gestion_token
  for update of r;

  if v_reserva_id is null then
    raise exception 'RESERVATION_NOT_FOUND';
  end if;

  if lower(coalesce(v_estado, '')) in ('cancelada', 'cancelado') then
    return jsonb_build_object(
      'ok', true,
      'duplicate', true,
      'reserva_id', v_reserva_id,
      'estado', 'cancelada'
    );
  end if;

  if v_inicio_at < now() + make_interval(mins => v_cancelacion_minutos) then
    raise exception 'CANCELLATION_WINDOW_CLOSED';
  end if;

  update public.reservas
  set estado = 'cancelada',
      cancelada_at = now(),
      mesa_id = null
  where id = v_reserva_id;

  return jsonb_build_object(
    'ok', true,
    'duplicate', false,
    'reserva_id', v_reserva_id,
    'estado', 'cancelada'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.completar_invitacion_restaurante()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_restaurante_id uuid;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  update public.restaurant_invitations
  set status = 'accepted',
      accepted_at = coalesce(accepted_at, now())
  where auth_user_id = v_user_id
    and status in ('sent', 'accepted');

  select ur.restaurante_id
    into v_restaurante_id
  from public.usuarios_restaurantes ur
  where ur.user_id = v_user_id
  order by ur.created_at asc, ur.restaurante_id asc
  limit 1;

  if v_restaurante_id is null then
    raise exception 'RESTAURANT_ACCESS_MISSING';
  end if;

  return jsonb_build_object('ok', true, 'restaurante_id', v_restaurante_id);
end;
$function$

