    v_precio := null;

    if v_id_text like 'menu-%' then
      if substring(v_id_text from 6) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        v_menu_id := substring(v_id_text from 6)::uuid;

        select m.titulo as nombre, m.precio
          into v_producto
