    values (v_pedido_id, v_producto_id, v_nombre, v_precio, v_qty, v_notas);

    v_total := v_total + (v_precio * v_qty);
  end loop;

  update public.pedidos_qr
     set total = v_total,
         updated_at = now()
   where id = v_pedido_id;

  return jsonb_build_object('ok', true, 'pedido_id', v_pedido_id, 'total', v_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.crear_reserva_manual(p_restaurante_id uuid, p_inicio_at timestamp with time zone, p_personas integer, p_nombre text, p_telefono text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_zona_horaria text;
  v_min_personas integer;
  v_max_personas integer;
  v_cliente_id uuid;
  v_reserva_id uuid;
  v_gestion_token uuid;
  v_fin_at timestamptz;
  v_turno text;
  v_telefono text;
  v_email text := nullif(lower(left(trim(coalesce(p_email, '')), 254)), '');
  v_nombre text := nullif(left(regexp_replace(trim(coalesce(p_nombre, '')), '\s+', ' ', 'g'), 120), '');
  v_notas text := nullif(left(trim(coalesce(p_notas, '')), 800), '');
  v_existing jsonb;
begin
  perform app_private.assert_mutation_allowed();

  if not public.user_can_access_restaurant(p_restaurante_id) then
    raise exception 'RESTAURANT_ACCESS_DENIED';
  end if;

  v_telefono := nullif(regexp_replace(coalesce(p_telefono, ''), '[^0-9]', '', 'g'), '');
  if v_telefono like '34%' and length(v_telefono) = 11 then
    v_telefono := substring(v_telefono from 3);
  end if;

  select c.zona_horaria, c.personas_minimas, c.personas_maximas
    into v_zona_horaria, v_min_personas, v_max_personas
  from public.reservas_config c
  where c.restaurante_id = p_restaurante_id;

  if v_zona_horaria is null then
    raise exception 'BOOKING_SETTINGS_NOT_FOUND';
  end if;

  if p_inicio_at is null
     or v_nombre is null or length(v_nombre) < 2
     or p_personas is null
     or p_personas < v_min_personas or p_personas > v_max_personas
     or (v_telefono is null and v_email is null)
     or (v_telefono is not null and length(v_telefono) not between 7 and 15)
     or (v_email is not null and v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$') then
    raise exception 'INVALID_BOOKING_REQUEST';
  end if;

  if p_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(p_restaurante_id::text || ':manual:' || p_idempotency_key::text, 0)
    );

    select jsonb_build_object(
      'ok', true,
      'duplicate', true,
      'reserva_id', r.id,
      'estado', r.estado,
      'inicio_at', r.inicio_at,
      'fin_at', r.fin_at,
      'gestion_token', r.gestion_token
    )
    into v_existing
    from public.reservas r
    where r.restaurante_id = p_restaurante_id
      and r.idempotency_key = p_idempotency_key
    limit 1;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_restaurante_id::text || ':date:'
        || (p_inicio_at at time zone v_zona_horaria)::date::text,
      0
    )
  );

  select a.fin_at, a.turno
    into v_fin_at, v_turno
  from public.obtener_disponibilidad_manual(
    p_restaurante_id,
    (p_inicio_at at time zone v_zona_horaria)::date,
    p_personas
  ) a
  where a.inicio_at = p_inicio_at
  limit 1;

  if v_fin_at is null then
    raise exception 'SLOT_NOT_AVAILABLE';
  end if;

  if v_telefono is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(p_restaurante_id::text || ':client-phone:' || v_telefono, 0)
    );

    select c.id into v_cliente_id
    from public.clientes c
    where c.restaurante_id = p_restaurante_id
      and regexp_replace(coalesce(c.telefono, ''), '[^0-9]', '', 'g')
        in (v_telefono, '34' || v_telefono)
    order by c.created_at asc nulls last, c.id asc
    limit 1;
  else
    perform pg_advisory_xact_lock(
      hashtextextended(p_restaurante_id::text || ':client-email:' || v_email, 0)
    );

    select c.id into v_cliente_id
    from public.clientes c
    where c.restaurante_id = p_restaurante_id
      and lower(c.email) = v_email
    order by c.created_at asc nulls last, c.id asc
    limit 1;
  end if;

  if v_cliente_id is null then
    insert into public.clientes (
      restaurante_id,
      nombre,
      telefono,
      email,
      origen_principal,
      canal_contacto,
      permite_whatsapp,
      permite_email,
      updated_at
    ) values (
      p_restaurante_id,
      v_nombre,
      v_telefono,
      v_email,
      'panel',
      'ninguno',
      false,
      false,
      now()
    )
    returning id into v_cliente_id;
  else
    update public.clientes
    set nombre = v_nombre,
        telefono = coalesce(v_telefono, telefono),
        email = coalesce(v_email, email),
        origen_principal = coalesce(origen_principal, 'panel'),
        updated_at = now()
    where id = v_cliente_id;
  end if;

  insert into public.reservas (
    restaurante_id,
    cliente_id,
    nombre_cliente,
    telefono,
    email,
    personas,
    origen,
    notas,
    fecha_hora_reserva,
    inicio_at,
    fin_at,
    estado,
    turno,
    idempotency_key
  ) values (
    p_restaurante_id,
    v_cliente_id,
    v_nombre,
    v_telefono,
    v_email,
    p_personas,
    'panel_nativo',
    v_notas,
    p_inicio_at at time zone v_zona_horaria,
    p_inicio_at,
    v_fin_at,
    'pendiente',
    v_turno,
    p_idempotency_key
  )
  returning id, gestion_token into v_reserva_id, v_gestion_token;

  return jsonb_build_object(
    'ok', true,
    'duplicate', false,
    'reserva_id', v_reserva_id,
    'estado', 'pendiente',
    'inicio_at', p_inicio_at,
    'fin_at', v_fin_at,
    'gestion_token', v_gestion_token
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.crear_reserva_publica_con_aceptacion(p_slug text, p_inicio_at timestamp with time zone, p_personas integer, p_nombre text, p_telefono text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_notas text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid, p_privacidad_informada boolean DEFAULT false, p_condiciones_aceptadas boolean DEFAULT false, p_version_legal text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_reserva_id uuid;
begin
  if p_privacidad_informada is not true
     or p_condiciones_aceptadas is not true
     or nullif(trim(coalesce(p_version_legal, '')), '') is null then
    raise exception 'LEGAL_ACCEPTANCE_REQUIRED';
  end if;

  v_result := public.crear_reserva_publica(
    p_slug,
    p_inicio_at,
    p_personas,
    p_nombre,
    p_telefono,
    p_email,
    p_notas,
    p_idempotency_key
  );

  v_reserva_id := nullif(v_result ->> 'reserva_id', '')::uuid;

  update public.reservas
  set privacidad_informada_at = coalesce(privacidad_informada_at, now()),
      condiciones_aceptadas_at = coalesce(condiciones_aceptadas_at, now()),
      version_legal = coalesce(version_legal, left(trim(p_version_legal), 40))
  where id = v_reserva_id;

  if not found then
    raise exception 'BOOKING_LEGAL_AUDIT_FAILED';
  end if;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_pedido_qr_session_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform pg_advisory_xact_lock(
    hashtextextended(new.mesa_id::text || ':' || new.mesa_session_id::text, 0)
  );

  if (
    select count(*)
    from public.pedidos_qr p
    where p.mesa_id = new.mesa_id
      and p.mesa_session_id = new.mesa_session_id
      and p.created_at > now() - interval '1 minute'
  ) >= 5 then
    raise exception 'DEMASIADOS_PEDIDOS';
  end if;

  if (
    select count(*)
    from public.pedidos_qr p
    where p.mesa_id = new.mesa_id
      and p.mesa_session_id = new.mesa_session_id
  ) >= 40 then
    raise exception 'LIMITE_SESION_ALCANZADO';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_reservation_automation(p_event_id text, p_event_type text, p_reservation_id uuid, p_restaurante_id uuid, p_cliente_id uuid, p_scheduled_for timestamp with time zone, p_payload jsonb, p_channel text DEFAULT 'auto'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_config public.automatizaciones_config%rowtype;
  v_modules public.restaurante_modulos%rowtype;
  v_status text := 'pending';
  v_error text;
begin
  if nullif(trim(coalesce(p_event_id, '')), '') is null
     or nullif(trim(coalesce(p_event_type, '')), '') is null
     or p_restaurante_id is null then
    raise exception 'INVALID_AUTOMATION_EVENT';
  end if;

  select * into v_config
  from public.automatizaciones_config
  where restaurante_id = p_restaurante_id;

  select * into v_modules
  from public.restaurante_modulos
  where restaurante_id = p_restaurante_id;

  if v_config.restaurante_id is null or v_config.enabled is not true then
    v_status := 'skipped';
    v_error := 'automation_disabled';
  elsif v_config.delivery_mode = 'paused' then
    v_status := 'skipped';
    v_error := 'delivery_paused';
  elsif coalesce(v_modules.automatizaciones, false) is not true then
    v_status := 'skipped';
    v_error := 'module_disabled';
  elsif p_event_type = 'visit.review_request'
        and (v_config.review_enabled is not true or coalesce(v_modules.resenas, false) is not true) then
    v_status := 'skipped';
    v_error := 'review_disabled';
  elsif p_event_type like 'loyalty.%'
        and (v_config.loyalty_enabled is not true or coalesce(v_modules.fidelizacion, false) is not true) then
    v_status := 'skipped';
    v_error := 'loyalty_disabled';
  elsif p_event_type = 'reservation.reminder'
        and (v_config.reminder_enabled is not true or p_scheduled_for <= now()) then
    v_status := 'skipped';
    v_error := case when v_config.reminder_enabled is true then 'reminder_too_late' else 'reminder_disabled' end;
  elsif p_event_type = 'reservation.created' and v_config.confirmation_enabled is not true then
    v_status := 'skipped';
    v_error := 'confirmation_disabled';
  end if;

  insert into public.reservation_webhook_deliveries (
    event_id,
    event_type,
    reservation_id,
    restaurante_id,
    cliente_id,
    payload,
    status,
    attempts,
    scheduled_for,
    channel,
    delivery_mode,
    last_error,
    first_attempt_at,
    last_attempt_at,
    updated_at
  ) values (
    left(p_event_id, 240),
    left(p_event_type, 80),
    p_reservation_id,
    p_restaurante_id,
    p_cliente_id,
    coalesce(p_payload, '{}'::jsonb),
    v_status,
    0,
    coalesce(p_scheduled_for, now()),
    case when p_channel in ('auto', 'whatsapp', 'email', 'internal') then p_channel else 'auto' end,
    coalesce(v_config.delivery_mode, 'paused'),
    v_error,
    now(),
    now(),
    now()
  )
  on conflict (event_id) do nothing;

  return left(p_event_id, 240);
end;
$function$

CREATE OR REPLACE FUNCTION public.gestionar_mesa_reserva(p_reserva_id uuid, p_mesa_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reserva public.reservas%rowtype;
begin
  perform app_private.assert_mutation_allowed();

  select r.* into v_reserva
  from public.reservas r
  where r.id = p_reserva_id
  for update;

  if v_reserva.id is null then
    raise exception 'RESERVATION_NOT_FOUND';
