  if not public.user_can_access_restaurant(v_reserva.restaurante_id) then
    raise exception 'RESTAURANT_ACCESS_DENIED';
  end if;

  update public.reservas
  set mesa_id = p_mesa_id
  where id = p_reserva_id;

