CREATE OR REPLACE FUNCTION public.preparar_web_reservas_restaurante()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_base_slug text;
  v_web_slug text;
begin
  v_base_slug := translate(
    lower(trim(coalesce(new.nombre, 'restaurante'))),
    'áéíóúüñç',
    'aeiouunc'
  );
  v_base_slug := regexp_replace(v_base_slug, '[^a-z0-9]+', '-', 'g');
  v_base_slug := regexp_replace(v_base_slug, '(^-|-$)', '', 'g');
  v_base_slug := coalesce(nullif(v_base_slug, ''), 'restaurante');
  v_web_slug := v_base_slug || '-' || substring(replace(new.id::text, '-', '') from 1 for 6);

  insert into public.restaurante_webs (
    restaurante_id, slug, publicada, nombre_publico, titular
  ) values (
    new.id, v_web_slug, false, new.nombre, new.nombre
  )
  on conflict (restaurante_id) do nothing;

  insert into public.reservas_config (restaurante_id, activo)
  values (new.id, false)
  on conflict (restaurante_id) do nothing;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.procesar_usuario_invitado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_invitation_id uuid;
  v_restaurante_id uuid;
  v_invitation_email text;
  v_demo_restaurante constant uuid := 'd1000000-0000-4000-8000-000000000001'::uuid;
  v_reputation_restaurante uuid;
begin
  if lower(coalesce(new.email, '')) = 'fixture-account-1@example.invalid' then
    insert into public.usuarios_restaurantes (user_id, restaurante_id, demo_vista)
    values (new.id, v_demo_restaurante, true)
    on conflict (user_id, restaurante_id)
    do update set demo_vista = true;

    update public.restaurantes
    set owner_id = new.id
    where id = v_demo_restaurante;

    update auth.users
    set email_confirmed_at = coalesce(email_confirmed_at, now()),
        raw_app_meta_data = jsonb_build_object(
          'provider', 'email',
          'providers', jsonb_build_array('email')
        ),
        raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
          || jsonb_build_object(
            'email_verified', true,
            'phone_verified', false,
            'demo', true
          ),
        updated_at = now()
    where id = new.id;

    return new;
  end if;

  -- Accesos de Reputation Suite vinculados a Hispanos Grill.
  if lower(coalesce(new.email, '')) in ('fixture-account-2@example.invalid', 'fixture-account-3@example.invalid') then
    select oc.restaurante_id
      into v_reputation_restaurante
    from public.opinion_config oc
    where oc.slug = 'fixture-reputation-restaurant'
      and oc.active = true
    limit 1;

    if v_reputation_restaurante is null then
      raise exception 'REPUTATION_RESTAURANT_NOT_FOUND';
    end if;

    insert into public.opinion_usuarios_restaurantes (
      user_id, restaurante_id, role, active
    ) values (
      new.id, v_reputation_restaurante, 'restaurante', true
    )
    on conflict (user_id, restaurante_id)
    do update set role = 'restaurante', active = true;

    update auth.users
    set email_confirmed_at = coalesce(email_confirmed_at, now()),
        raw_app_meta_data = jsonb_build_object(
          'provider', 'email',
          'providers', jsonb_build_array('email')
        ),
        raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
          || jsonb_build_object(
            'email_verified', true,
            'phone_verified', false,
            'acceso', 'reputacion'
          ),
        updated_at = now()
    where id = new.id;

    return new;
  end if;

  begin
    v_invitation_id := nullif(new.raw_user_meta_data ->> 'invitation_id', '')::uuid;
  exception
    when invalid_text_representation then
      raise exception 'INVITE_REQUIRED';
  end;

  if v_invitation_id is null then
    raise exception 'INVITE_REQUIRED';
  end if;

  select i.restaurante_id, lower(i.email)
    into v_restaurante_id, v_invitation_email
  from public.restaurant_invitations i
  where i.id = v_invitation_id
    and i.status = 'pending'
    and i.auth_user_id is null
  for update;

  if not found
     or v_invitation_email <> lower(coalesce(new.email, ''))
     or v_restaurante_id::text <> coalesce(new.raw_user_meta_data ->> 'restaurante_id', '') then
    raise exception 'INVALID_RESTAURANT_INVITATION';
  end if;

  insert into public.usuarios_restaurantes (user_id, restaurante_id)
  values (new.id, v_restaurante_id)
  on conflict (user_id, restaurante_id) do nothing;

  update public.restaurantes
  set owner_id = new.id
  where id = v_restaurante_id;

  update public.restaurant_invitations
  set auth_user_id = new.id,
      status = 'sent',
      sent_at = now()
  where id = v_invitation_id;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.procesar_visita_cliente()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$DECLARE
  v_payload json;
BEGIN
  -- Solo cuando pasa a "ha venido"
  IF OLD.atendida IS NOT NULL OR NEW.atendida IS DISTINCT FROM true THEN
    RETURN NEW;
  END IF;

  -- Solo si hay email
  IF NEW.email IS NULL THEN
    RETURN NEW;
  END IF;

  -- Payload para n8n
  v_payload := json_build_object(
    'reserva_id', NEW.id,
    'email', NEW.email,
    'cliente_id', NEW.cliente_id,
    'restaurante_id', NEW.restaurante_id,
    'fecha', NEW.fecha_hora_reserva,
    'personas', NEW.personas
  );

  -- Llamada a n8n
  PERFORM
    net.http_post(
      url := 'https://outbound-disabled.example.invalid/4',
      headers := '{"Content-Type":"application/json"}'::jsonb,
      body := v_payload
    );

  RETURN NEW;
END;$function$

