CREATE OR REPLACE FUNCTION public.reprogramar_reserva_publica_gestion(p_gestion_token uuid, p_nuevo_inicio_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reserva_id uuid;
  v_restaurante_id uuid;
  v_slug text;
  v_zona_horaria text;
  v_cancelacion_minutos integer;
  v_personas integer;
  v_estado_anterior text;
  v_inicio_anterior timestamptz;
  v_nuevo_fin_at timestamptz;
  v_nuevo_turno text;
begin
  select
    r.id,
    r.restaurante_id,
    w.slug,
    c.zona_horaria,
    c.cancelacion_minutos,
    greatest(coalesce(r.personas, 1), 1),
    r.estado,
    coalesce(r.inicio_at, r.fecha_hora_reserva at time zone c.zona_horaria)
  into
    v_reserva_id,
    v_restaurante_id,
    v_slug,
    v_zona_horaria,
    v_cancelacion_minutos,
    v_personas,
    v_estado_anterior,
    v_inicio_anterior
  from public.reservas r
  join public.reservas_config c on c.restaurante_id = r.restaurante_id and c.activo = true
  join public.restaurante_webs w on w.restaurante_id = r.restaurante_id and w.publicada = true
  where r.gestion_token = p_gestion_token
  for update of r;

  if v_reserva_id is null then
    raise exception 'RESERVATION_NOT_FOUND';
  end if;

  if p_nuevo_inicio_at is null
     or lower(coalesce(v_estado_anterior, '')) in ('cancelada', 'cancelado', 'no-show', 'no_show') then
    raise exception 'RESERVATION_CANNOT_BE_RESCHEDULED';
  end if;

  if v_inicio_anterior < now() + make_interval(mins => v_cancelacion_minutos) then
    raise exception 'CANCELLATION_WINDOW_CLOSED';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      v_restaurante_id::text || ':date:'
        || (p_nuevo_inicio_at at time zone v_zona_horaria)::date::text,
      0
    )
  );

  -- Dentro de esta transaccion liberamos temporalmente la reserva actual para
  -- que no reste su propia capacidad al comprobar la nueva hora.
  update public.reservas
  set estado = 'cancelada'
  where id = v_reserva_id;

  select a.fin_at, a.turno
    into v_nuevo_fin_at, v_nuevo_turno
  from public.obtener_disponibilidad_reservas(
    v_slug,
    (p_nuevo_inicio_at at time zone v_zona_horaria)::date,
    v_personas
  ) a
  where a.inicio_at = p_nuevo_inicio_at
  limit 1;

  if v_nuevo_fin_at is null then
    raise exception 'SLOT_NOT_AVAILABLE';
  end if;

  update public.reservas
  set inicio_at = p_nuevo_inicio_at,
      fin_at = v_nuevo_fin_at,
      fecha_hora_reserva = p_nuevo_inicio_at at time zone v_zona_horaria,
      turno = v_nuevo_turno,
      estado = v_estado_anterior,
      cancelada_at = null,
      mesa_id = null
  where id = v_reserva_id;

  return jsonb_build_object(
    'ok', true,
    'reserva_id', v_reserva_id,
    'estado', v_estado_anterior,
    'inicio_at', p_nuevo_inicio_at,
    'fin_at', v_nuevo_fin_at,
    'turno', v_nuevo_turno
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_canjear_premio(p_cliente_id uuid, p_restaurante_id uuid, p_premio_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cost integer;
  v_saldo integer;
  v_canje_id uuid;
begin
  if not exists (
    select 1
    from public.clientes c
    where c.id = p_cliente_id
      and c.restaurante_id = p_restaurante_id
  ) then
    raise exception 'Cliente no disponible';
  end if;

  select p.puntos_requeridos
    into v_cost
  from public.premios_puntos p
  where p.id = p_premio_id
    and p.restaurante_id = p_restaurante_id
    and p.activo is true
  limit 1;

  if v_cost is null then
    raise exception 'Premio no disponible';
  end if;

  select s.puntos
    into v_saldo
  from public.puntos_saldos s
  where s.cliente_id = p_cliente_id
    and s.restaurante_id = p_restaurante_id
  for update;

  v_saldo := coalesce(v_saldo, 0);

  select c.id
    into v_canje_id
  from public.canjes_puntos c
  where c.cliente_id = p_cliente_id
    and c.restaurante_id = p_restaurante_id
    and c.premio_id = p_premio_id
    and c.estado = 'pendiente'
  order by c.creado_en desc, c.id desc
  limit 1;

  if v_canje_id is not null then
    return v_canje_id;
  end if;

  if v_saldo < v_cost then
    raise exception 'Puntos insuficientes';
  end if;

  insert into public.canjes_puntos (
    cliente_id,
    restaurante_id,
    premio_id,
    puntos_usados,
    estado
  ) values (
    p_cliente_id,
    p_restaurante_id,
    p_premio_id,
    v_cost,
    'pendiente'
  )
  returning id into v_canje_id;

  begin
    insert into public.puntos_movimientos (
      cliente_id,
      restaurante_id,
      tipo,
      puntos,
      referencia,
      nota
    ) values (
      p_cliente_id,
      p_restaurante_id,
      'canje',
      -v_cost,
      v_canje_id::text,
      'Canje de premio'
    );
  exception
    when check_violation then
      raise exception 'Puntos insuficientes';
  end;

  return v_canje_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.rpc_registrar_gasto(p_cliente_id uuid, p_restaurante_id uuid, p_gasto numeric)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ratio int;
  v_puntos int;
begin
  select puntos_por_euro
  into v_ratio
  from public.fidelizacion_config
  where restaurante_id = p_restaurante_id;

  if v_ratio is null or v_ratio <= 0 then
    raise exception 'Falta fidelizacion_config para el restaurante';
  end if;

  v_puntos := floor(p_gasto * v_ratio);

  if v_puntos <= 0 then
    return 0;
  end if;

  insert into public.puntos_movimientos (cliente_id, restaurante_id, tipo, puntos, referencia, nota)
  values (p_cliente_id, p_restaurante_id, 'ticket', v_puntos, 'gasto', 'Puntos por gasto');

  return v_puntos;
end;
$function$

