CREATE OR REPLACE FUNCTION public.sincronizar_fecha_reserva_nativa()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_zona_horaria text;
  v_duracion integer;
begin
  select c.zona_horaria, c.duracion_minutos
    into v_zona_horaria, v_duracion
  from public.reservas_config c
  where c.restaurante_id = new.restaurante_id;

  v_zona_horaria := coalesce(v_zona_horaria, 'Europe/Madrid');
  v_duracion := coalesce(v_duracion, 90);

  if tg_op = 'UPDATE'
     and new.fecha_hora_reserva is distinct from old.fecha_hora_reserva
     and new.inicio_at is not distinct from old.inicio_at then
    new.inicio_at := new.fecha_hora_reserva at time zone v_zona_horaria;
    new.fin_at := new.inicio_at + make_interval(mins => v_duracion);
  elsif new.inicio_at is not null then
    new.fecha_hora_reserva := new.inicio_at at time zone v_zona_horaria;
    if tg_op = 'UPDATE' and new.inicio_at is distinct from old.inicio_at then
      new.fin_at := new.inicio_at + make_interval(mins => v_duracion);
    else
      new.fin_at := coalesce(new.fin_at, new.inicio_at + make_interval(mins => v_duracion));
    end if;
  elsif new.fecha_hora_reserva is not null then
    new.inicio_at := new.fecha_hora_reserva at time zone v_zona_horaria;
    new.fin_at := coalesce(new.fin_at, new.inicio_at + make_interval(mins => v_duracion));
  end if;

  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.storage_object_restaurant_id(p_bucket_id text, p_object_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_folders text[] := storage.foldername(p_object_name);
  v_candidate text;
begin
  if p_bucket_id = 'menus' and v_folders[1] = 'productos' then
    v_candidate := v_folders[2];
  elsif p_bucket_id = 'premios' then
    v_candidate := v_folders[1];
  else
    return null;
  end if;

  if v_candidate ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return v_candidate::uuid;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_due_automation_events(p_limit integer DEFAULT 25)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.reservation_webhook_deliveries%rowtype;
  v_config public.automatizaciones_config%rowtype;
  v_client public.clientes%rowtype;
  v_consent public.cliente_comunicaciones_consentimiento%rowtype;
  v_body jsonb;
  v_customer jsonb;
  v_url text;
  v_request_id bigint;
  v_whatsapp_allowed boolean;
  v_email_allowed boolean;
  v_submitted integer := 0;
begin
  for v_event in
    select * from public.claim_reservation_automation_events(p_limit)
  loop
    begin
      select * into v_config
      from public.automatizaciones_config
      where restaurante_id = v_event.restaurante_id;

      if v_event.cliente_id is not null then
        select * into v_client
        from public.clientes
        where id = v_event.cliente_id
          and restaurante_id = v_event.restaurante_id;

        select * into v_consent
        from public.cliente_comunicaciones_consentimiento
        where cliente_id = v_event.cliente_id
          and restaurante_id = v_event.restaurante_id
          and revoked_at is null;
      end if;

      v_body := coalesce(v_event.payload, '{}'::jsonb);
      v_customer := coalesce(v_body -> 'customer', '{}'::jsonb);
      v_whatsapp_allowed := v_config.whatsapp_enabled
        and nullif(trim(coalesce(v_customer ->> 'phone', '')), '') is not null;
      v_email_allowed := v_config.email_enabled
        and nullif(trim(coalesce(v_customer ->> 'email', '')), '') is not null;

      if v_event.delivery_mode = 'live' and v_event.event_type = 'visit.review_request' then
        v_whatsapp_allowed := v_whatsapp_allowed
          and coalesce(v_client.permite_whatsapp, false)
          and coalesce(v_consent.review_whatsapp, false);
        v_email_allowed := v_email_allowed
          and coalesce(v_client.permite_email, false)
          and coalesce(v_consent.review_email, false);
      elsif v_event.delivery_mode = 'live' and v_event.event_type like 'loyalty.%' then
        v_whatsapp_allowed := v_whatsapp_allowed
          and coalesce(v_client.permite_whatsapp, false)
          and coalesce(v_consent.loyalty_whatsapp, false);
        v_email_allowed := v_email_allowed
          and coalesce(v_client.permite_email, false)
          and coalesce(v_consent.loyalty_email, false);
      end if;

      if v_event.delivery_mode = 'live'
         and v_event.event_type in ('visit.review_request', 'loyalty.points_awarded')
         and not v_whatsapp_allowed
         and not v_email_allowed then
        update public.reservation_webhook_deliveries
        set status = 'skipped',
            last_error = 'marketing_consent_missing',
            locked_at = null,
            lock_token = null,
            updated_at = now()
        where event_id = v_event.event_id
          and lock_token = v_event.lock_token;
        continue;
      end if;

      if v_event.delivery_mode = 'live'
         and v_event.event_type not in ('automation.test')
         and not v_whatsapp_allowed
         and not v_email_allowed then
        update public.reservation_webhook_deliveries
        set status = 'skipped',
            last_error = 'delivery_channel_unavailable',
            locked_at = null,
            lock_token = null,
            updated_at = now()
        where event_id = v_event.event_id
          and lock_token = v_event.lock_token;
        continue;
      end if;

      if v_event.delivery_mode = 'test' then
        v_customer := v_customer || jsonb_build_object('phone', null, 'email', null);
        v_whatsapp_allowed := false;
        v_email_allowed := false;
      end if;

      v_body := jsonb_set(v_body, '{customer}', v_customer, true)
        || jsonb_build_object(
          'event', v_event.event_type,
          'automationEventId', v_event.event_id,
          'reservationId', v_event.reservation_id,
          'restaurantId', v_event.restaurante_id,
          'clientId', v_event.cliente_id,
          'channel', v_event.channel,
          'deliveryMode', v_event.delivery_mode,
          'suppressDelivery', v_event.delivery_mode = 'test',
          'whatsappAllowed', v_whatsapp_allowed,
          'emailAllowed', v_email_allowed,
          'managementUrl', case
            when nullif(v_body ->> 'managementPath', '') is null then null
            else 'https://outbound-disabled.example.invalid/5' || (v_body ->> 'managementPath')
          end,
          'reviewUrl', case
            when nullif(v_body ->> 'reviewPath', '') is null then null
            else 'https://outbound-disabled.example.invalid/5' || (v_body ->> 'reviewPath')
          end,
          'attempt', v_event.attempts
        );

      v_url := case
        when v_event.event_type = 'visit.review_request'
          then 'https://outbound-disabled.example.invalid/4'
        else 'https://outbound-disabled.example.invalid/6'
      end;

      v_request_id := net.http_post(
        url := v_url,
        body := v_body,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'X-GastroHelp-Automation-Event', v_event.event_id,
          'X-GastroHelp-Delivery-Mode', v_event.delivery_mode
        ),
        timeout_milliseconds := 12000
      );

      update public.reservation_webhook_deliveries
      set net_request_id = v_request_id,
          submitted_at = now(),
          updated_at = now()
      where event_id = v_event.event_id
        and lock_token = v_event.lock_token;

      v_submitted := v_submitted + 1;
    exception
      when others then
        perform public.complete_reservation_automation_event(
          v_event.event_id,
          v_event.lock_token,
          false,
          null,
          left(sqlerrm, 1000)
        );
    end;
  end loop;

  return v_submitted;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_opinion_qr(p_slug text, p_rating integer, p_comentario text DEFAULT NULL::text, p_nombre_cliente text DEFAULT NULL::text, p_origen text DEFAULT 'desconocido'::text, p_submission_token uuid DEFAULT gen_random_uuid(), p_consentimiento_privacidad boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_restaurante_id uuid;
  v_opinion_id uuid;
  v_origen text;
begin
  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'Valoración no válida' using errcode = '22023';
  end if;

  if coalesce(p_consentimiento_privacidad, false) is not true then
    raise exception 'Consentimiento de privacidad requerido' using errcode = '22023';
  end if;

  if p_comentario is not null and char_length(trim(p_comentario)) > 2000 then
    raise exception 'Comentario demasiado largo' using errcode = '22001';
  end if;

  if p_nombre_cliente is not null and char_length(trim(p_nombre_cliente)) > 100 then
    raise exception 'Nombre demasiado largo' using errcode = '22001';
  end if;

  select oc.restaurante_id
    into v_restaurante_id
  from public.opinion_config oc
  where oc.slug = lower(trim(p_slug))
    and oc.active = true
  limit 1;

  if v_restaurante_id is null then
    raise exception 'Sistema de opiniones no disponible' using errcode = 'P0002';
  end if;

  v_origen := case lower(coalesce(trim(p_origen), 'desconocido'))
    when 'mesa' then 'mesa'
    when 'caja' then 'caja'
    when 'entrada' then 'entrada'
    when 'portacuentas' then 'portacuentas'
    when 'redes' then 'redes'
    else 'desconocido'
  end;

  insert into public.opiniones_qr (
    restaurante_id,
    rating,
    comentario,
    nombre_cliente,
    origen,
    submission_token,
    consentimiento_privacidad
  ) values (
    v_restaurante_id,
    p_rating,
    nullif(trim(coalesce(p_comentario, '')), ''),
    nullif(trim(coalesce(p_nombre_cliente, '')), ''),
    v_origen,
    coalesce(p_submission_token, gen_random_uuid()),
    true
  )
  on conflict (submission_token) do nothing
  returning id into v_opinion_id;

  if v_opinion_id is null then
    select oq.id into v_opinion_id
    from public.opiniones_qr oq
    where oq.submission_token = p_submission_token
      and oq.restaurante_id = v_restaurante_id
    limit 1;
  end if;

  return v_opinion_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_opinion_qr_v2(p_slug text, p_rating integer, p_comentario text DEFAULT NULL::text, p_nombre_cliente text DEFAULT NULL::text, p_origen text DEFAULT 'desconocido'::text, p_submission_token uuid DEFAULT gen_random_uuid(), p_consentimiento_privacidad boolean DEFAULT false, p_aspectos text[] DEFAULT '{}'::text[], p_contacto text DEFAULT NULL::text, p_contacto_tipo text DEFAULT 'ninguno'::text, p_solicita_contacto boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_restaurante_id uuid;
  v_opinion_id uuid;
  v_origen text;
  v_aspectos text[] := '{}'::text[];
  v_contacto text;
  v_contacto_tipo text := 'ninguno';
  v_threshold smallint := 3;
begin
  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'Valoración no válida' using errcode = '22023';
  end if;
  if not coalesce(p_consentimiento_privacidad, false) then
    raise exception 'Consentimiento requerido' using errcode = '22023';
  end if;
  if p_comentario is not null and char_length(trim(p_comentario)) > 2000 then
    raise exception 'Comentario demasiado largo' using errcode = '22001';
  end if;
  if p_nombre_cliente is not null and char_length(trim(p_nombre_cliente)) > 100 then
    raise exception 'Nombre demasiado largo' using errcode = '22001';
  end if;
  if p_contacto is not null and char_length(trim(p_contacto)) > 160 then
    raise exception 'Contacto demasiado largo' using errcode = '22001';
  end if;

  select oc.restaurante_id, oc.low_rating_threshold
    into v_restaurante_id, v_threshold
  from public.opinion_config oc
  where oc.slug = lower(trim(p_slug)) and oc.active = true
  limit 1;

  if v_restaurante_id is null then
    raise exception 'Sistema de opiniones no disponible' using errcode = 'P0002';
  end if;

  v_origen := case lower(coalesce(trim(p_origen), 'desconocido'))
    when 'mesa' then 'mesa'
    when 'caja' then 'caja'
    when 'entrada' then 'entrada'
    when 'portacuentas' then 'portacuentas'
    when 'redes' then 'redes'
    else 'desconocido'
  end;

  select coalesce(array_agg(item), '{}'::text[])
    into v_aspectos
  from (
    select distinct lower(trim(value)) as item
    from unnest(coalesce(p_aspectos, '{}'::text[])) as value
    where lower(trim(value)) = any(array[
      'comida','servicio','ambiente','espera','limpieza','calidad_precio'
    ]::text[])
    limit 6
  ) allowed;

  if coalesce(p_solicita_contacto, false) then
    v_contacto_tipo := case lower(coalesce(trim(p_contacto_tipo), 'ninguno'))
      when 'telefono' then 'telefono'
      when 'email' then 'email'
      else 'ninguno'
    end;
    v_contacto := nullif(trim(coalesce(p_contacto, '')), '');
    if v_contacto is null then
      v_contacto_tipo := 'ninguno';
    end if;
  end if;

  insert into public.opiniones_qr (
    restaurante_id, rating, comentario, nombre_cliente, origen,
    submission_token, consentimiento_privacidad, aspectos,
    contacto, contacto_tipo, solicita_contacto
  ) values (
    v_restaurante_id, p_rating,
    nullif(trim(coalesce(p_comentario, '')), ''),
    nullif(trim(coalesce(p_nombre_cliente, '')), ''),
    v_origen, coalesce(p_submission_token, gen_random_uuid()),
    true, v_aspectos, v_contacto, v_contacto_tipo,
    coalesce(p_solicita_contacto, false) and v_contacto is not null
  )
  on conflict (submission_token) do nothing
  returning id into v_opinion_id;

  if v_opinion_id is null then
    select id into v_opinion_id
    from public.opiniones_qr
    where submission_token = p_submission_token
      and restaurante_id = v_restaurante_id
    limit 1;
  end if;

  if p_rating <= v_threshold then
    insert into public.opinion_alertas (
      restaurante_id, opinion_id, tipo, destino_email, destino_whatsapp, payload
    )
    select v_restaurante_id, v_opinion_id, 'valoracion_baja',
           oc.feedback_email, oc.feedback_whatsapp,
           jsonb_build_object('rating', p_rating, 'origen', v_origen)
    from public.opinion_config oc
    where oc.restaurante_id = v_restaurante_id
    on conflict (opinion_id, tipo) do nothing;
  end if;

  if coalesce(p_solicita_contacto, false) and v_contacto is not null then
    insert into public.opinion_alertas (
      restaurante_id, opinion_id, tipo, destino_email, destino_whatsapp, payload
    )
    select v_restaurante_id, v_opinion_id, 'seguimiento_solicitado',
           oc.feedback_email, oc.feedback_whatsapp,
           jsonb_build_object('contacto_tipo', v_contacto_tipo, 'origen', v_origen)
    from public.opinion_config oc
    where oc.restaurante_id = v_restaurante_id
    on conflict (opinion_id, tipo) do nothing;
  end if;

  return v_opinion_id;
end;
$function$

