CREATE OR REPLACE FUNCTION public.track_opinion_event(p_slug text, p_submission_token uuid, p_event_type text, p_origen text DEFAULT 'desconocido'::text, p_rating integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_restaurante_id uuid;
  v_event_id uuid;
  v_event_type text;
  v_origen text;
begin
  v_event_type := lower(trim(coalesce(p_event_type, '')));
  if v_event_type <> all(array[
    'view','rating_selected','details_opened','submitted',
    'copy_succeeded','copy_failed','google_opened','returned_from_google'
  ]::text[]) then
    raise exception 'Evento no válido' using errcode = '22023';
  end if;

  if p_rating is not null and (p_rating < 1 or p_rating > 5) then
    raise exception 'Valoración no válida' using errcode = '22023';
  end if;

  select oc.restaurante_id into v_restaurante_id
  from public.opinion_config oc
  where oc.slug = lower(trim(p_slug)) and oc.active = true
  limit 1;

  if v_restaurante_id is null then
    raise exception 'Sistema de opiniones no disponible' using errcode = 'P0002';
  end if;

  v_origen := case lower(coalesce(trim(p_origen), 'desconocido'))
    when 'mesa' then 'mesa'
    when 'caja' then 'caja'
    when 'entrada' then 'entrada'
    when 'portacuentas' then 'portacuentas'
    when 'redes' then 'redes'
    else 'desconocido'
  end;

  insert into public.opinion_eventos (
    restaurante_id, submission_token, event_type, origen, rating
  ) values (
    v_restaurante_id, p_submission_token, v_event_type, v_origen,
    case when p_rating between 1 and 5 then p_rating else null end
  ) returning id into v_event_id;

  if v_event_type = 'google_opened' and p_submission_token is not null then
    update public.opiniones_qr
    set google_abierto = true,
        google_abierto_at = coalesce(google_abierto_at, now())
    where restaurante_id = v_restaurante_id
      and submission_token = p_submission_token;
  end if;

  return v_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_clientes_historial_gasto_a_puntos()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_ppe numeric;
  v_puntos integer;
  v_ref text;
  v_activo boolean := false;
begin
  if new.tipo is distinct from 'visita' then
    return new;
  end if;

  if new.gasto_eur is null then
    return new;
  end if;

  select coalesce(r.puntos_activo, false) and coalesce(m.fidelizacion, false)
    into v_activo
    from public.restaurantes r
    left join public.restaurante_modulos m
      on m.restaurante_id = r.id
   where r.id = new.restaurante_id
   limit 1;

  if not coalesce(v_activo, false) then
    return new;
  end if;

  v_ref := 'visita:' || coalesce(new.reserva_id::text, new.id::text);

  select fc.puntos_por_euro
    into v_ppe
    from public.fidelizacion_config fc
   where fc.restaurante_id = new.restaurante_id
   limit 1;

  if v_ppe is null then
    select r.puntos_por_euro
      into v_ppe
      from public.restaurantes r
     where r.id = new.restaurante_id
     limit 1;
  end if;

  v_ppe := coalesce(v_ppe, 1);
  v_puntos := floor(new.gasto_eur * v_ppe);

  if v_puntos <= 0 then
    return new;
  end if;

  insert into public.puntos_movimientos (
    cliente_id,
    restaurante_id,
    tipo,
    puntos,
    referencia,
    nota
  )
  values (
    new.cliente_id,
    new.restaurante_id,
    'ticket',
    v_puntos,
    v_ref,
    'puntos por gasto (visita)'
  )
  on conflict do nothing;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_puntos_movimientos_apply_saldo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_curr int;
  v_new  int;
begin
  if tg_op = 'INSERT' then
    select puntos
      into v_curr
    from public.puntos_saldos
    where cliente_id = new.cliente_id
      and restaurante_id = new.restaurante_id
    for update;

    v_curr := coalesce(v_curr, 0);
    v_new  := v_curr + coalesce(new.puntos, 0);

    if v_new < 0 then
      raise exception 'Puntos insuficientes';
    end if;

    insert into public.puntos_saldos (cliente_id, restaurante_id, puntos, actualizado_en)
    values (new.cliente_id, new.restaurante_id, v_new, now())
    on conflict (cliente_id, restaurante_id)
    do update set
      puntos = excluded.puntos,
      actualizado_en = now();

    return new;
  end if;

  if tg_op = 'DELETE' then
    select puntos
      into v_curr
    from public.puntos_saldos
    where cliente_id = old.cliente_id
      and restaurante_id = old.restaurante_id
    for update;

    v_curr := coalesce(v_curr, 0);
    v_new  := v_curr - coalesce(old.puntos, 0);

    if v_new < 0 then
      v_new := 0;
    end if;

    update public.puntos_saldos
    set puntos = v_new,
        actualizado_en = now()
    where cliente_id = old.cliente_id
      and restaurante_id = old.restaurante_id;

    return old;
  end if;

  if tg_op = 'UPDATE' then
    -- si cambia (cliente/restaurante), ajustamos ambos lados
    if (old.cliente_id, old.restaurante_id) = (new.cliente_id, new.restaurante_id) then
      select puntos
        into v_curr
      from public.puntos_saldos
      where cliente_id = new.cliente_id
        and restaurante_id = new.restaurante_id
      for update;

      v_curr := coalesce(v_curr, 0);
      v_new  := v_curr - coalesce(old.puntos, 0) + coalesce(new.puntos, 0);

      if v_new < 0 then
        raise exception 'Puntos insuficientes';
      end if;

      update public.puntos_saldos
      set puntos = v_new,
          actualizado_en = now()
      where cliente_id = new.cliente_id
        and restaurante_id = new.restaurante_id;

      return new;
    end if;

    -- quitar old
    select puntos
      into v_curr
    from public.puntos_saldos
    where cliente_id = old.cliente_id
      and restaurante_id = old.restaurante_id
    for update;

    v_curr := coalesce(v_curr, 0);
    v_new  := v_curr - coalesce(old.puntos, 0);
    if v_new < 0 then v_new := 0; end if;

    update public.puntos_saldos
    set puntos = v_new,
        actualizado_en = now()
    where cliente_id = old.cliente_id
      and restaurante_id = old.restaurante_id;

    -- sumar new
    select puntos
      into v_curr
    from public.puntos_saldos
    where cliente_id = new.cliente_id
      and restaurante_id = new.restaurante_id
    for update;

    v_curr := coalesce(v_curr, 0);
    v_new  := v_curr + coalesce(new.puntos, 0);

    if v_new < 0 then
      raise exception 'Puntos insuficientes';
    end if;

    insert into public.puntos_saldos (cliente_id, restaurante_id, puntos, actualizado_en)
    values (new.cliente_id, new.restaurante_id, v_new, now())
    on conflict (cliente_id, restaurante_id)
    do update set
      puntos = excluded.puntos,
      actualizado_en = now();

    return new;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_puntos_movimientos_sync_saldo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cliente uuid;
  v_rest uuid;
  v_total int;
begin
  -- Determinar “par” afectado
  if tg_op = 'DELETE' then
    v_cliente := old.cliente_id;
    v_rest := old.restaurante_id;
  else
    v_cliente := new.cliente_id;
    v_rest := new.restaurante_id;
  end if;

  -- Recalcular total
  select coalesce(sum(pm.puntos), 0)::int
    into v_total
  from public.puntos_movimientos pm
  where pm.cliente_id = v_cliente
    and pm.restaurante_id = v_rest;

  -- Upsert saldo (si total 0, puedes borrar fila)
  if v_total = 0 then
    delete from public.puntos_saldos
    where cliente_id = v_cliente and restaurante_id = v_rest;
  else
    insert into public.puntos_saldos (cliente_id, restaurante_id, puntos, actualizado_en)
    values (v_cliente, v_rest, v_total, now())
    on conflict (cliente_id, restaurante_id)
    do update set
      puntos = excluded.puntos,
      actualizado_en = now();
  end if;

  -- Si en UPDATE cambió cliente/restaurante, recalcular también el “old”
  if tg_op = 'UPDATE' then
    if (old.cliente_id is distinct from new.cliente_id)
       or (old.restaurante_id is distinct from new.restaurante_id) then

      select coalesce(sum(pm.puntos), 0)::int
        into v_total
      from public.puntos_movimientos pm
      where pm.cliente_id = old.cliente_id
        and pm.restaurante_id = old.restaurante_id;

      if v_total = 0 then
        delete from public.puntos_saldos
        where cliente_id = old.cliente_id and restaurante_id = old.restaurante_id;
      else
        insert into public.puntos_saldos (cliente_id, restaurante_id, puntos, actualizado_en)
        values (old.cliente_id, old.restaurante_id, v_total, now())
        on conflict (cliente_id, restaurante_id)
        do update set
          puntos = excluded.puntos,
          actualizado_en = now();
      end if;
    end if;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.trigger_automation_panel_dispatch()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_nonce uuid;
  v_request_id bigint;
begin
  delete from public.automation_dispatch_nonces
  where expires_at <= now();

  insert into public.automation_dispatch_nonces default values
  returning nonce into v_nonce;

  v_request_id := net.http_post(
    url := 'https://outbound-disabled.example.invalid/7',
    body := jsonb_build_object('nonce', v_nonce),
    headers := jsonb_build_object('Content-Type', 'application/json'),
    timeout_milliseconds := 55000
  );

  return v_request_id;
end;
$function$
